package service; import java.util.*; import model.*; import exceptions.TokenNotFoundException;
public class QueueService {
 public synchronized Token generateToken(String student,int service,boolean priority){PriorityQueue<Token> q=DataStore.serviceQueues.get(service);if(q==null||DataStore.findService(service)==null)return null;for(Token t:DataStore.tokenHistory)if(t.getStudentId().equalsIgnoreCase(student)&&t.getServiceId()==service&&(t.getStatus().equals("Waiting")||t.getStatus().equals("Called")||t.getStatus().equals("Serving")))return null;Token t=new Token(++DataStore.tokenCounter,student,service,priority);q.offer(t);DataStore.tokenIds.add(t.getTokenId());DataStore.tokenMap.put(t.getTokenId(),t);DataStore.tokenHistory.add(t);DataStore.save();return t;}
 public synchronized int getPosition(int id){Token t=DataStore.tokenMap.get(id);if(t==null||!t.getStatus().equals("Waiting"))return -1;PriorityQueue<Token> q=DataStore.serviceQueues.get(t.getServiceId());if(q==null)return -1;PriorityQueue<Token> copy=new PriorityQueue<>(q);int p=1;while(!copy.isEmpty()){if(copy.poll().getTokenId()==id)return p;p++;}return -1;}
 public int getWaitingTime(int id){Token t=DataStore.tokenMap.get(id);if(t==null)return -1;int p=getPosition(id);if(p<=0)return 0;Service s=DataStore.findService(t.getServiceId());return s==null?0:(p-1)*s.getAverageServiceTime();}
 public synchronized void cancelToken(int id)throws TokenNotFoundException{Token t=DataStore.tokenMap.get(id);if(t==null)throw new TokenNotFoundException("Token not found.");if(!t.getStatus().equals("Waiting"))throw new IllegalStateException("Only waiting tokens can be cancelled.");DataStore.serviceQueues.get(t.getServiceId()).remove(t);t.setStatus("Cancelled");DataStore.save();}
 public synchronized Token callNextToken(int service){if(hasActive(service))return null;PriorityQueue<Token> q=DataStore.serviceQueues.get(service);if(q==null||q.isEmpty())return null;Token t=q.poll();t.setStatus("Called");DataStore.save();return t;}
 private boolean hasActive(int service){for(Token t:DataStore.tokenHistory)if(t.getServiceId()==service&&(t.getStatus().equals("Called")||t.getStatus().equals("Serving")))return true;return false;}
 public synchronized boolean startServing(Token t){if(t==null||!t.getStatus().equals("Called"))return false;t.setStatus("Serving");DataStore.save();return true;}
 public synchronized boolean completeToken(Token t){if(t==null||!t.getStatus().equals("Serving"))return false;t.setStatus("Completed");DataStore.save();return true;}
 public synchronized boolean skipToken(Token t){if(t==null||!t.getStatus().equals("Called"))return false;t.setStatus("Skipped");DataStore.save();return true;}
 public List<Token> getStudentTokens(String id){List<Token> r=new ArrayList<>();for(Token t:DataStore.tokenHistory)if(t.getStudentId().equalsIgnoreCase(id))r.add(t);r.sort(Comparator.comparing(Token::getArrivalTime).reversed());return r;}
 public List<Token> getQueueSnapshot(int service){PriorityQueue<Token> q=DataStore.serviceQueues.get(service);if(q==null)return Collections.emptyList();List<Token> r=new ArrayList<>(q);r.sort(DataStore.TOKEN_ORDER);return r;}
 public Token findToken(int id)throws TokenNotFoundException{Token t=DataStore.tokenMap.get(id);if(t==null)throw new TokenNotFoundException("Token "+id+" was not found.");return t;}
}
